    def soft_id(self):

        localctx = GASDParser.Soft_idContext(self, self._ctx, self.state)
        self.enterRule(localctx, 168, self.RULE_soft_id)
        self._la = 0 # Token type
        try:
            self.enterOuterAlt(localctx, 1)
            self.state = 1814
            _la = self._input.LA(1)
            if not(((((_la - 5)) & ~0x3f) == 0 and ((1 << (_la - 5)) & -2251799813685249) != 0) or ((((_la - 69)) & ~0x3f) == 0 and ((1 << (_la - 69)) & 2305843010287435775) != 0)):
                self._errHandler.recoverInline(self)
            else:
                self._errHandler.reportMatch(self)
                self.consume()
        except RecognitionException as re:
            localctx.exception = re
            self._errHandler.reportError(self, re)
            self._errHandler.recover(self, re)
        finally:
            self.exitRule()
        return localctx



    def sempred(self, localctx:RuleContext, ruleIndex:int, predIndex:int):
        if self._predicates == None:
            self._predicates = dict()
        self._predicates[3] = self.version_number_sempred
        self._predicates[54] = self.legacy_case_step_sempred
        self._predicates[60] = self.contract_arithmetic_sempred
        self._predicates[70] = self.value_sempred
        self._predicates[78] = self.expr_sempred
        pred = self._predicates.get(ruleIndex, None)
        if pred is None:
            raise Exception("No predicate with index:" + str(ruleIndex))
        else:
            return pred(localctx, predIndex)

    def version_number_sempred(self, localctx:Version_numberContext, predIndex:int):
            if predIndex == 0:
                return not self._input.LT(1).text.startswith('-')


    def legacy_case_step_sempred(self, localctx:Legacy_case_stepContext, predIndex:int):
            if predIndex == 1:
                return self._input.LA(1) != self.WHEN_KW
         

    def contract_arithmetic_sempred(self, localctx:Contract_arithmeticContext, predIndex:int):
            if predIndex == 2:
                return self.precpred(self._ctx, 3)
         

            if predIndex == 3:
                return self.precpred(self._ctx, 2)
         

            if predIndex == 4:
                return self.precpred(self._ctx, 1)
         

    def value_sempred(self, localctx:ValueContext, predIndex:int):
            if predIndex == 5:
                return self.precpred(self._ctx, 4)


            if predIndex == 6:
                return self.precpred(self._ctx, 3)


            if predIndex == 7:
                return self.precpred(self._ctx, 6)


            if predIndex == 8:
                return self.precpred(self._ctx, 5)


            if predIndex == 9:
                return self.precpred(self._ctx, 2)
         

    def expr_sempred(self, localctx:ExprContext, predIndex:int):
            if predIndex == 10:
                return self.precpred(self._ctx, 5)
         

            if predIndex == 11:
                return self.precpred(self._ctx, 4)
         

            if predIndex == 12:
                return self.precpred(self._ctx, 3)
         

            if predIndex == 13:
                return self.precpred(self._ctx, 2)
         




